const txns = ($json.data) || [];
const accts = (($('Get Accounts').first()||{json:{}}).json.data) || [];
const q=(s)=> (s===null||s===undefined)?'NULL':("'"+String(s).replace(/'/g,"''")+"'");
const num=(v)=>{const x=Number(v); return Number.isFinite(x)?x:0;};
function acctName(a){ const dd=(a.debit_details&&a.debit_details[0])||{}; return dd.account_name||''; }
const trows=[]; const seen=new Set();
for(const t of txns){ if(!t.id||seen.has(t.id)) continue; seen.add(t.id); const ai=t.additional_info||{};
  trows.push('('+[q(t.id),q(t.account_id),(t.datetime?('TIMESTAMPTZ '+q(t.datetime)):'NULL'),q(t.type),q(t.channel),q(t.status),q(t.currency_code),(num(t.amount)/100),num(t.amount),q(t.reference),q(t.counterparty_name),q(ai.spend_category),q(ai.card_holder),q(ai.card_name),q(ai.card_number),q(ai.card_id),num(t.balance),'now()'].join(',')+')'); }
const arows=[];
for(const a of accts){ if(!a.id) continue; arows.push('('+[q(a.id),q(a.account_status),q(a.account_type),q(a.currency_code),num(a.available_balance),(num(a.available_balance)/100),q(acctName(a)),'now()'].join(',')+')'); }
let sql='CREATE SCHEMA IF NOT EXISTS finance; ';
sql+='CREATE TABLE IF NOT EXISTS finance.aspire_transactions (id text PRIMARY KEY, account_id text, datetime timestamptz, type text, channel text, status text, currency_code text, amount numeric, amount_cents bigint, reference text, counterparty_name text, spend_category text, card_holder text, card_name text, card_number text, card_id text, balance_cents bigint, loaded_at timestamptz default now()); ';
sql+='CREATE TABLE IF NOT EXISTS finance.aspire_accounts (id text PRIMARY KEY, account_status text, account_type text, currency_code text, available_balance_cents bigint, available_balance numeric, account_name text, snapshot_at timestamptz default now()); ';
if(trows.length) sql+='INSERT INTO finance.aspire_transactions (id,account_id,datetime,type,channel,status,currency_code,amount,amount_cents,reference,counterparty_name,spend_category,card_holder,card_name,card_number,card_id,balance_cents,loaded_at) VALUES '+trows.join(',')+' ON CONFLICT (id) DO UPDATE SET status=EXCLUDED.status, amount=EXCLUDED.amount, amount_cents=EXCLUDED.amount_cents, spend_category=EXCLUDED.spend_category, card_holder=EXCLUDED.card_holder, balance_cents=EXCLUDED.balance_cents, loaded_at=now(); ';
if(arows.length) sql+='INSERT INTO finance.aspire_accounts (id,account_status,account_type,currency_code,available_balance_cents,available_balance,account_name,snapshot_at) VALUES '+arows.join(',')+' ON CONFLICT (id) DO UPDATE SET available_balance_cents=EXCLUDED.available_balance_cents, available_balance=EXCLUDED.available_balance, account_status=EXCLUDED.account_status, snapshot_at=now(); ';
return [{json:{query:sql, txns:trows.length, accts:arows.length}}];
